import numpy as np
import numba

# Pre-compile numba versions for common dtypes
@numba.njit(fastmath=True)
def _outer_numba_f8(v1, v2):
    n = v1.shape[0]
    out = np.empty((n, n), dtype=np.float64)
    for i in range(n):
        vi = v1[i]
        for j in range(n):
            out[i, j] = vi * v2[j]
    return out

@numba.njit(fastmath=True)
def _outer_numba_f4(v1, v2):
