    return out

class Solver:
    def __init__(self):
        # Warmup all numba functions to pre-compile
        dummy_f8 = np.zeros(1, dtype=np.float64)
        dummy_f4 = np.zeros(1, dtype=np.float32)
        dummy_i8 = np.zeros(1, dtype=np.int64)
        dummy_i4 = np.zeros(1, dtype=np.int32)

        _outer_numba_f8(dummy_f8, dummy_f8)
        _outer_numba_f4(dummy_f4, dummy_f4)
        _outer_numba_i8(dummy_i8, dummy_i8)
        _outer_numba_i4(dummy_i4, dummy_i4)

        # Auto-detect threshold
        self.threshold = self._find_threshold()
        self._last_n = 0
        self._out_buffer = None

    def _find_threshold(self):
        """Find the size where numpy multiply.outer becomes faster than numba."""
        import time

        # Warmup numpy too
        v = np.random.randn(100).astype(np.float64)
        for _ in range(5):
            np.multiply.outer(v, v)
            _outer_numba_f8(v, v)

        # Binary search-like approach
        # Test sizes from small to large, find first where numpy wins
        test_sizes = [100, 300, 500, 700, 900, 1100, 1300, 1500, 1700, 1900, 2100, 2500, 3000]
        threshold = 3000  # default fallback

        for n in test_sizes:
            v1 = np.random.randn(n).astype(np.float64)
            v2 = np.random.randn(n).astype(np.float64)

            # Adapt iteration count to get reliable timing
            n_iter = max(5, min(50000 // (n * n), 200))

            # Time numba
            t0 = time.perf_counter()
            for _ in range(n_iter):
                _outer_numba_f8(v1, v2)
            t_numba = (time.perf_counter() - t0) / n_iter

            # Time numpy
            t0 = time.perf_counter()
            for _ in range(n_iter):
                np.multiply.outer(v1, v2)
            t_numpy = (time.perf_counter() - t0) / n_iter

            if t_numba > t_numpy:
                threshold = n
                break
            threshold = n  # numba still better

        return threshold

    def solve(self, problem, **kwargs):
        vec1, vec2 = problem
        # Ensure ndarray (copy=False for efficiency)
        vec1 = np.asarray(vec1)
        vec2 = np.asarray(vec2)

        n = vec1.shape[0]
        dtype = vec1.dtype

        # Small size: use numba
        if n <= self.threshold:
            if dtype == np.float64:
                return _outer_numba_f8(vec1, vec2)
            elif dtype == np.float32:
                return _outer_numba_f4(vec1, vec2)
            elif dtype == np.int64 or dtype == np.int_ or dtype == np.longlong:
                return _outer_numba_i8(vec1.astype(np.int64), vec2.astype(np.int64))
            elif dtype == np.int32:
                return _outer_numba_i4(vec1.astype(np.int32), vec2.astype(np.int32))
            else:
                # Generic: convert to float64
                return _outer_numba_f8(vec1.astype(np.float64), vec2.astype(np.float64))
        else:
            # Large size: use numpy
            return np.multiply.outer(vec1, vec2)
